import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingIssuesTagDefinitionsRetrieve } from '../../generated/api'
import type { ErrorTrackingIssueTagDefinitionApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueTagDefinitionsLogicValues {
    issueTagDefinitions: ErrorTrackingIssueTagDefinitionApi[] | null
    issueTagDefinitionsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueTagDefinitionsLogicActions {
    loadIssueTagDefinitions: () => any
    loadIssueTagDefinitionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadIssueTagDefinitionsSuccess: (
        issueTagDefinitions: ErrorTrackingIssueTagDefinitionApi[],
        payload?: any
    ) => {
        issueTagDefinitions: ErrorTrackingIssueTagDefinitionApi[]
        payload?: any
    }
}

export type issueTagDefinitionsLogicType = MakeLogicType<
    issueTagDefinitionsLogicValues,
    issueTagDefinitionsLogicActions
>

export const issueTagDefinitionsLogic = kea<issueTagDefinitionsLogicType>([
    path(['products', 'error_tracking', 'components', 'IssueFilters', 'issueTagDefinitionsLogic']),

    loaders(() => ({
        issueTagDefinitions: [
            null as ErrorTrackingIssueTagDefinitionApi[] | null,
            {
                loadIssueTagDefinitions: async () => {
                    const response = await errorTrackingIssuesTagDefinitionsRetrieve(
                        String(teamLogic.values.currentTeamId)
                    )
                    return response.results
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadIssueTagDefinitions()
    }),
])
